    sim_rio_tormenta_c: (h, ev) => `río ${h} m${ev ? " (evacuación)" : ""}`, sim_rio_sin_dato_c: "río sin dato", sim_evac_corto: "evacuación",
    sim_r_desague: (v) => `lluvia de 1 h de cada 2 años aquí: ${v} mm/h`,
    sim_tabla_t: "Todos los Niños desde 1951 (informativo)", sim_tabla_sub: "Solo los Niños desde 1997-98 tienen todos los datos (lluvia del satélite IMERG y del reanálisis ERA5, y altura de los ríos): son los del selector y los únicos que entran en el cálculo del peor. La lluvia es la del satélite: en tormentas de 100 mm o más da el 82 % de lo medido en pluviómetros del INA y del SMN, contra el 60 % de ERA5; en 1997-98 todavía no había IMERG. El río es el de los días de cada tormenta. Antes de 1997 solo hay ERA5, que subestima, y no hay caudal de los ríos.",
    sim_tabla_int: "Intensidad", sim_tabla_lluvia: "Peor tormenta (3 días)", sim_tabla_rio: "Río en la tormenta", sim_tabla_pers: "Personas con agua (estimado)", sim_tabla_datos: "Datos",
