    sim_r_desague: (v) => `1-hour rain that recurs every 2 years here: ${v} mm/h`,
    sim_tabla_t: "Every El Niño since 1951 (for reference)", sim_tabla_sub: "Only El Niño seasons since 1997-98 have every input (IMERG satellite and ERA5 reanalysis rain, and river levels): they are the ones in the selector and the only ones in the worst-case estimate. Rain comes from the satellite: in storms of 100 mm or more it gives 82% of what rain gauges measured (INA and SMN), against 60% for ERA5; IMERG did not exist yet in 1997-98. The river is the one on each storm's days. Before 1997 there is only ERA5, which underestimates, and no river flow.",
    sim_tabla_int: "Strength", sim_tabla_lluvia: "Worst storm (3 days)", sim_tabla_rio: "River during the storm", sim_tabla_pers: "People with water (estimate)", sim_tabla_datos: "Data",
