    dc_muni: (m) => `${m}: level of each day`,
    dc_unidad: "% of area",
    dc_pie: "Tap a column to see that day on the map.",
    dc_tocar: "Tap to see this day on the map",
    info_dc_t: "For each day, which share of the area (of the selection or the country) is at each risk level; each column adds up to 100 %. Tap a column and the map shows that day.",
    cb_t: "What changes in the coming days",
    cb_horizonte: "Next",
    cb_sube: "Rising",
    cb_sigue: (i) => `stays high${i ? ` · peak ${i === 1 ? "tomorrow" : `in ${i} days`}` : ""}`,
    cb_baja: "Falling",
    cb_todos: (n) => `See all ${n}`,
    cb_menos: "See less",
    cb_vacio_sube: (n) => `No area rises in level in the next ${n} days.`,
    cb_vacio_sigue: (n) => `No area stays at high risk in the next ${n} days.`,
    cb_vacio_baja: (n) => `No area falls in level in the next ${n} days.`,
    cb_causa_lluvia: "Rain",
    cb_causa_rio: "River",
    cb_causa_alerta: "SMN warning",
    cb_nota: "Today's level → the highest of the period. It is a forecast: the further the day, the more uncertain.",
    info_cb_t: "Compares each municipality's risk level today with the highest of the coming days. Rising: those getting worse and in how many days. Stays high: those already at high or very high risk that stay there. Falling: those improving. The advice comes from the leading hazard (rain, river or warning) and local data (low ground, sewers).",
    rec_lluvia: (T, p, d) => `3-day rainfall like the one that falls once every ${T} years (${p} % of forecasts). Before ${d}: clear drains and gutters, lift valuables off the floor and avoid streets that flood.`,
    rec_rio: (e, n, p, d) => `River rising${e ? ` (station ${e})` : ""} to ${n} level (${p} % of forecasts) by ${d}: prepare to evacuate and follow the river stage at INA.`,
    rec_alerta: (n, d) => `SMN ${n} warning for ${d}: follow Civil Defence instructions and avoid travelling.`,
    rec_baja: "The hazard drops: a good time to clear drains and check damage.",
    rec_bajo: (p) => `${p} % live on low ground: prioritise those blocks.`,
    rec_cloaca: (p) => `${p} % have no sewer: protect drinking water.`,
    cb_tab_sube: "Rising",
    cb_tab_sigue: "Stay high",
    cb_tab_baja: "Falling",
    prop_t: "Propensity to hold water",
    info_prop_t: "How much the place tends to hold water, 0 to 10, with the same traffic light as risk: area that ever had water (Landsat 1984-2021), new water in the 2015-16 and 2023-24 Niños (Dynamic World) and ground less than 2 m above the nearest stream; in the hills, slope and clay. It does not depend on the forecast: risk can be green today while propensity is yellow or red. With normal rain it enters each day's risk, so it never reads 0 where the ground holds water. It is the municipality's value: it does not know each property's drainage.",
    comp_terreno: "Terrain propensity (fixed)",
    sim_k_pers_a: "People living (2022 Census) in areas with 10 cm of water or more. The Census counts where people live, not where they work: a factory's staff is not included; for that, see the industry indicator.",
    sim_k_ind: "Industry",
    sim_k_ind_a: "Area of factories, warehouses and shops (OpenStreetMap industrial and commercial zones) with 10 cm of water or more at the wettest moment. It does not know each property's drainage: it is the water the ground would hold if nobody drained it.",
    sim_ind_de: (t) => `of ${t} ha`,
    sim_ind_no: "No industrial areas on the map",
    sim_prof_corto: (p) => `up to ${p} m`,
    pron_f_rio_pron: (e, h, d) => `measured today by INA at ${e}; then each day's forecast stage (GloFAS with the station curve, anchored to today's reading): up to ${h} m on ${d}`,
